// ScamTrace India - draws the charts and tables from data.js (window.SCAMTRACE).
// data.js is generated by scripts/export_site_data.py from the dbt marts.

const D = window.SCAMTRACE;
const charts = [];

// ---------- small helpers ----------------------------------------------

// read a colour token from style.css, so charts follow light/dark mode
const css = name => getComputedStyle(document.documentElement).getPropertyValue(name).trim();

// Indian digit grouping: 1,28,265 not 128,265
const fmt = (n, digits = 0) =>
  n === null || n === undefined ? "–"
    : Number(n).toLocaleString("en-IN", { minimumFractionDigits: digits, maximumFractionDigits: digits });

const sum = (rows, key) => rows.reduce((total, r) => total + (r[key] || 0), 0);

function makeTable(id, columns, rows, highlight = () => false) {
  const head = "<tr>" + columns.map(c => `<th>${c.label}</th>`).join("") + "</tr>";
  const body = rows.map(r =>
    `<tr class="${highlight(r) ? "hl" : ""}">` +
    columns.map(c => `<td>${c.show ? c.show(r[c.key], r) : r[c.key]}</td>`).join("") +
    "</tr>").join("");
  document.getElementById(id).innerHTML = head + body;
}

// draws dashed median lines on a chart (x and/or y), used as threshold markers
function medianLines(xValue, yValue) {
  return {
    id: "medianLines",
    afterDatasetsDraw(chart) {
      const { ctx, chartArea: area, scales } = chart;
      ctx.save();
      ctx.strokeStyle = css("--muted");
      ctx.lineWidth = 1;
      ctx.setLineDash([4, 4]);
      if (xValue !== null) {
        const x = scales.x.getPixelForValue(xValue);
        ctx.beginPath(); ctx.moveTo(x, area.top); ctx.lineTo(x, area.bottom); ctx.stroke();
      }
      if (yValue !== null) {
        const y = scales.y.getPixelForValue(yValue);
        ctx.beginPath(); ctx.moveTo(area.left, y); ctx.lineTo(area.right, y); ctx.stroke();
      }
      ctx.restore();
    },
  };
}

function baseOptions() {
  return {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: { display: false },          // legends are written in the HTML
      tooltip: {
        backgroundColor: css("--surface"),
        titleColor: css("--text"),
        bodyColor: css("--text-2"),
        borderColor: css("--axis"),
        borderWidth: 1,
        padding: 10,
      },
    },
    scales: {
      x: { grid: { color: css("--grid") }, border: { color: css("--axis") }, ticks: { color: css("--muted") } },
      y: { grid: { color: css("--grid") }, border: { color: css("--axis") }, ticks: { color: css("--muted") } },
    },
  };
}

// ---------- stat tiles ---------------------------------------------------

function drawTiles() {
  const latest = D.cases_by_year[D.cases_by_year.length - 1];
  const f2023 = D.funnel_by_year.find(r => r.year === 2023);
  const firsPer100 = sum(D.quadrant, "firs") / sum(D.quadrant, "complaints") * 100;
  const frozenPct = sum(D.money_2023, "amount_saved_cr") / sum(D.money_2023, "amount_reported_cr") * 100;

  const tiles = [
    [fmt(latest.cases), `cyber crime FIRs registered in ${latest.year}`, "NCRB"],
    ["≤ " + fmt(firsPer100, 1), "FIRs for every 100 fraud complaints on the portal (2023)", "NCRB ÷ I4C, upper bound"],
    [fmt(f2023.convicted), `convictions in 2023, against ${fmt(f2023.portal_complaints)} fraud complaints`, "NCRB, I4C"],
    [fmt(frozenPct, 1) + "%", "of money reported lost was frozen in time (2023)", "I4C CFCFRMS"],
  ];
  document.getElementById("tiles").innerHTML = tiles.map(([value, label, src]) =>
    `<div class="tile"><div class="value">${value}</div><div class="label">${label}</div><div class="src">${src}</div></div>`
  ).join("");
  drawDataStrip();
}

// ---------- which years the data covers + when it was last updated -------

function drawDataStrip() {
  const c = D.coverage;
  const span = ([a, b]) => (a === b ? `${a}` : `${a}–${b}`);
  const updated = new Date(D.generated + "T00:00:00")
    .toLocaleDateString("en-IN", { day: "numeric", month: "long", year: "numeric" });
  const items = [
    ["Police FIRs", span(c.fir_years)],
    ["Fraud funnel", span(c.funnel_years)],
    ["Complaints & money", String(c.complaint_year)],
    ["Fraud types", span(c.type_years)],
  ];
  document.getElementById("dataStrip").innerHTML =
    `<span class="ds-label">Data covers</span>` +
    items.map(([k, v]) => `<span class="ds-item">${k} <b>${v}</b></span>`).join("") +
    `<span class="ds-updated">Last updated <b>${updated}</b></span>` +
    `<span class="ds-source">Newest source: ${c.newest_source}. ` +
    `Official figures are published 1–2 years late, so ${c.fir_years[1]} is the latest year available.</span>`;
}

// ---------- 1. quadrant --------------------------------------------------

const WEAK = "High rate, weak enforcement";
const LABELLED = ["Delhi", "Chandigarh", "Haryana", "Gujarat", "Rajasthan", "Karnataka",
                  "Telangana", "Uttar Pradesh", "Kerala", "Bihar", "Odisha"];
// where each name goes relative to its bubble (default: above) - set by hand
// for the few bubbles that sit close together
const LABEL_SIDE = { "Delhi": "below", "Rajasthan": "right", "Uttar Pradesh": "left" };

function drawQuadrant() {
  const medX = D.quadrant[0].median_complaints_per_100k;
  const medY = D.quadrant[0].median_firs_per_100_complaints;

  const point = r => ({
    x: r.complaints_per_100k, y: r.firs_per_100_complaints,
    r: 3 + Math.sqrt(r.complaints) / 30,       // bubble area grows with complaints
    row: r,
  });

  // writes the state name next to a few bubbles, in text colour (not the series colour)
  const stateLabels = {
    id: "stateLabels",
    afterDatasetsDraw(chart) {
      const { ctx } = chart;
      ctx.save();
      const a = chart.chartArea;
      // on a phone there is only room for a few names and short captions
      const narrow = chart.width < 560;
      const labelled = narrow ? ["Delhi", "Karnataka", "Telangana", "Gujarat"] : LABELLED;
      ctx.fillStyle = css("--text-2");
      ctx.font = "12px system-ui, sans-serif";
      chart.data.datasets.forEach((ds, i) => {
        chart.getDatasetMeta(i).data.forEach((el, j) => {
          const { row, r } = ds.data[j];
          if (!labelled.includes(row.state)) return;
          const side = narrow ? "above" : (LABEL_SIDE[row.state] || "above");
          if (side === "right") {
            ctx.textAlign = "left";
            ctx.fillText(row.state, el.x + r + 4, el.y + 4);
          } else if (side === "left") {
            ctx.textAlign = "right";
            ctx.fillText(row.state, el.x - r - 4, el.y + 4);
          } else {
            // centred above/below, nudged back inside the plot at the edges
            ctx.textAlign = "center";
            const half = ctx.measureText(row.state).width / 2;
            const x = Math.min(Math.max(el.x, a.left + half + 2), a.right - half - 2);
            ctx.fillText(row.state, x, side === "below" ? el.y + r + 13 : el.y - r - 4);
          }
        });
      });
      // quadrant names in the four corners (the band below 0 is kept empty for them)
      ctx.fillStyle = css("--muted");
      ctx.font = "600 11px system-ui, sans-serif";
      const weak = narrow ? "WEAK" : "WEAK ENFORCEMENT";
      ctx.textAlign = "right";
      ctx.fillText("HIGH RATE, COPING", a.right - 6, a.top + 14);
      ctx.fillText("HIGH RATE, " + weak, a.right - 6, a.bottom - 8);
      ctx.textAlign = "left";
      ctx.fillText("LOW RATE, COPING", a.left + 6, a.top + 14);
      ctx.fillText("LOW RATE, " + weak, a.left + 6, a.bottom - 8);
      ctx.restore();
    },
  };

  const options = baseOptions();
  options.scales.x.title = { display: true, text: "Fraud complaints per lakh people (I4C portal)", color: css("--text-2") };
  options.scales.y.title = { display: true, text: "Cyber FIRs per 100 complaints (NCRB ÷ I4C)", color: css("--text-2") };
  options.scales.x.min = 0;
  // an empty band below 0 holds the bottom quadrant names, so they don't sit
  // on top of the bubbles. Nothing is plotted there and it has no tick labels.
  options.scales.y.min = -4;
  options.scales.y.max = 40;
  options.scales.y.ticks.callback = v => (v < 0 ? "" : v);
  options.scales.y.grid.color = c => (c.tick.value < 0 ? "transparent" : css("--grid"));
  options.plugins.tooltip.callbacks = {
    title: items => items[0].raw.row.state,
    label: item => {
      const r = item.raw.row;
      return [
        `${fmt(r.complaints_per_100k, 1)} complaints per lakh (${fmt(r.complaints)} total)`,
        `${fmt(r.firs_per_100_complaints, 2)} FIRs per 100 complaints (${fmt(r.firs)} FIRs)`,
        `Complaint rank ${r.complaint_rank}, FIR rank ${r.fir_rank}`,
        `Fraud trials completed ${r.fraud_trials_completed}, convicted ${r.fraud_convicted}`,
        r.quadrant,
      ];
    },
  };

  charts.push(new Chart(document.getElementById("quadrantChart"), {
    type: "bubble",
    data: {
      datasets: [
        { label: "Other", data: D.quadrant.filter(r => r.quadrant !== WEAK).map(point),
          backgroundColor: css("--neutral"), borderColor: css("--surface"), borderWidth: 2, hoverRadius: 2 },
        { label: WEAK, data: D.quadrant.filter(r => r.quadrant === WEAK).map(point),
          backgroundColor: css("--series-2"), borderColor: css("--surface"), borderWidth: 2, hoverRadius: 2 },
      ],
    },
    options: {
      ...options,
      // clicking a bubble opens that state in the explorer at the top
      onClick: (event, hits, chart) => {
        if (!hits.length || !window.ScamExplore) return;
        const hit = hits[0];
        window.ScamExplore.show(chart.data.datasets[hit.datasetIndex].data[hit.index].row.state);
      },
      onHover: (event, hits) => { event.native.target.style.cursor = hits.length ? "pointer" : "default"; },
    },
    plugins: [medianLines(medX, medY), stateLabels],
  }));

  makeTable("quadrantTable", [
    { key: "state", label: "State/UT" },
    { key: "complaints", label: "Complaints", show: v => fmt(v) },
    { key: "complaints_per_100k", label: "Per lakh", show: v => fmt(v, 1) },
    { key: "firs", label: "Cyber FIRs", show: v => fmt(v) },
    { key: "firs_per_100_complaints", label: "FIRs per 100 complaints", show: v => fmt(v, 2) },
    { key: "complaint_rank", label: "Complaint rank" },
    { key: "fir_rank", label: "FIR rank" },
    { key: "rank_gap", label: "Gap", show: v => (v > 0 ? "+" : "") + v },
    { key: "quadrant", label: "Quadrant" },
  ], D.quadrant, r => r.quadrant === WEAK);
}

// ---------- 1b. conversion bars -----------------------------------------

function drawConversion() {
  const rows = [...D.quadrant].sort((a, b) => b.firs_per_100_complaints - a.firs_per_100_complaints);
  const options = baseOptions();
  options.indexAxis = "y";
  options.scales.y.grid.display = false;
  options.scales.y.ticks.autoSkip = false;
  options.scales.y.ticks.color = css("--text-2");
  options.scales.x.title = { display: true, text: "FIRs per 100 complaints", color: css("--text-2") };
  options.plugins.tooltip.callbacks = {
    label: item => {
      const r = rows[item.dataIndex];
      return `${fmt(r.firs_per_100_complaints, 2)} FIRs per 100 complaints (${fmt(r.firs)} of ${fmt(r.complaints)})`;
    },
  };
  charts.push(new Chart(document.getElementById("conversionChart"), {
    type: "bar",
    data: {
      labels: rows.map(r => r.state),
      datasets: [{ data: rows.map(r => r.firs_per_100_complaints), backgroundColor: css("--series-1"),
                   borderRadius: 4, borderSkipped: "start", categoryPercentage: 0.8, barPercentage: 0.9 }],
    },
    options,
    plugins: [medianLines(D.quadrant[0].median_firs_per_100_complaints, null)],
  }));
}

// ---------- 2. rate -----------------------------------------------------

let rateYear = 2024;          // changed by the year buttons above the chart
let rateChart = null;

function median(values) {
  const v = [...values].sort((a, b) => a - b), mid = Math.floor(v.length / 2);
  return v.length % 2 ? v[mid] : (v[mid - 1] + v[mid]) / 2;
}

function drawRateYears() {
  const years = D.cases_by_year.map(r => r.year);
  const box = document.getElementById("rateYears");
  box.innerHTML = "";
  years.forEach(y => {
    const b = document.createElement("button");
    b.type = "button";
    b.textContent = y;
    b.setAttribute("aria-pressed", y === rateYear);
    b.onclick = () => { rateYear = y; drawRateYears(); drawRate(); };
    box.appendChild(b);
  });
}

function drawRate() {
  const all = D.state_years.filter(r => r.year === rateYear)
    .sort((a, b) => b.cases_per_100k - a.cases_per_100k);
  const national = D.cases_by_year.find(r => r.year === 2024).per_100k;
  document.getElementById("rate24").textContent = fmt(national, 2);
  document.getElementById("rateYearLabel").textContent = rateYear;
  document.getElementById("median24").textContent =
    fmt(median(all.map(r => r.cases_per_100k)), 2) + " per lakh in " + rateYear;

  // redraw only this chart when the year changes
  if (rateChart) {
    rateChart.destroy();
    if (charts.includes(rateChart)) charts.splice(charts.indexOf(rateChart), 1);
  }

  const top = all.slice(0, 20);
  const options = baseOptions();
  options.indexAxis = "y";
  options.scales.y.grid.display = false;
  options.scales.y.ticks.autoSkip = false;
  options.scales.y.ticks.color = css("--text-2");
  options.scales.x.title = { display: true, text: "Cyber crime FIRs per lakh people", color: css("--text-2") };
  options.plugins.tooltip.callbacks = {
    label: item => {
      const r = top[item.dataIndex];
      return [`${fmt(r.cases_per_100k, 2)} per lakh (${fmt(r.cyber_cases)} FIRs)`,
              `Rank by count ${r.rank_by_count}, rank by rate ${r.rank_by_rate}`, r.risk_band];
    },
  };
  rateChart = new Chart(document.getElementById("rateChart"), {
    type: "bar",
    data: {
      labels: top.map(r => r.state),
      datasets: [{ data: top.map(r => r.cases_per_100k),
                   backgroundColor: top.map(r => r.risk_band === "High risk" ? css("--series-2") : css("--series-1")),
                   borderRadius: 4, borderSkipped: "start", categoryPercentage: 0.8, barPercentage: 0.9 }],
    },
    options,
  });
  charts.push(rateChart);

  makeTable("rateTable", [
    { key: "state", label: "State/UT" },
    { key: "cyber_cases", label: "FIRs " + rateYear, show: v => fmt(v) },
    { key: "cases_per_100k", label: "Per lakh", show: v => fmt(v, 2) },
    { key: "rank_by_count", label: "Rank by count" },
    { key: "rank_by_rate", label: "Rank by rate" },
    { key: "risk_band", label: "Band" },
  ], all, r => r.risk_band === "High risk");
}

// ---------- 3. funnel (tables) -------------------------------------------

function drawFunnel() {
  const f = D.funnel_by_year.find(r => r.year === 2023);
  const stages = [
    ["Fraud complaints on the national portal (I4C)", f.portal_complaints],
    ["Cyber fraud FIRs registered (NCRB, Fraud head)", f.registered],
    ["Charge sheeted", f.charge_sheeted],
    ["Trial completed", f.trials_completed],
    ["Convicted", f.convicted],
  ].map(([stage, n]) => ({ stage, n, per_lakh: n / f.portal_complaints * 100000 }));

  makeTable("funnelTable", [
    { key: "stage", label: "Stage" },
    { key: "n", label: "Cases", show: v => fmt(v) },
    { key: "per_lakh", label: "Per lakh complaints", show: v => fmt(v, v < 100 ? 1 : 0) },
  ], stages, r => r.stage === "Convicted");

  makeTable("convictionTable", [
    { key: "year", label: "Year" },
    { key: "registered", label: "Registered", show: v => fmt(v) },
    { key: "trials_completed", label: "Trials done", show: v => fmt(v) },
    { key: "convicted", label: "Convicted", show: v => fmt(v) },
    { key: "rate", label: "Conviction rate", show: v => fmt(v, 1) + "%" },
  ], D.funnel_by_year.map(r => ({ ...r, rate: r.convicted / r.trials_completed * 100 })));
}

// ---------- 4. money ------------------------------------------------------

function drawMoney() {
  const top = D.money_2023.slice(0, 12);
  const options = baseOptions();
  options.indexAxis = "y";
  options.scales.y.grid.display = false;
  options.scales.y.ticks.color = css("--text-2");
  options.scales.x.title = { display: true, text: "₹ crore", color: css("--text-2") };
  options.plugins.tooltip.callbacks = {
    afterBody: items => `Frozen: ${fmt(top[items[0].dataIndex].pct_amount_saved, 1)}% of reported loss`,
  };
  const bar = { borderRadius: 4, borderSkipped: "start", categoryPercentage: 0.8, barPercentage: 0.92 };
  charts.push(new Chart(document.getElementById("moneyChart"), {
    type: "bar",
    data: {
      labels: top.map(r => r.state),
      datasets: [
        { label: "Reported lost (₹ cr)", data: top.map(r => r.amount_reported_cr), backgroundColor: css("--series-1"), ...bar },
        { label: "Frozen in time (₹ cr)", data: top.map(r => r.amount_saved_cr), backgroundColor: css("--series-2"), ...bar },
      ],
    },
    options,
  }));

  makeTable("moneyTable", [
    { key: "state", label: "State/UT" },
    { key: "amount_reported_cr", label: "Reported lost (₹ cr)", show: v => fmt(v, 2) },
    { key: "amount_saved_cr", label: "Frozen (₹ cr)", show: v => fmt(v, 2) },
    { key: "pct_amount_saved", label: "Frozen %", show: v => fmt(v, 1) },
    { key: "avg_loss_per_complaint_inr", label: "₹ per complaint", show: v => fmt(v) },
    { key: "loss_per_person_inr", label: "₹ per resident", show: v => fmt(v, 1) },
  ], D.money_2023);
}

// ---------- 5. growth -------------------------------------------------------

function drawGrowth() {
  const options = baseOptions();
  options.scales.x.grid.display = false;
  options.plugins.tooltip.callbacks = {
    label: item => {
      const r = D.cases_by_year[item.dataIndex];
      return `${fmt(r.cases)} FIRs (${fmt(r.per_100k, 2)} per lakh)`;
    },
  };
  charts.push(new Chart(document.getElementById("yearChart"), {
    type: "bar",
    data: {
      labels: D.cases_by_year.map(r => r.year),
      datasets: [{ data: D.cases_by_year.map(r => r.cases), backgroundColor: css("--series-1"),
                   borderRadius: 4, borderSkipped: "start", categoryPercentage: 0.7 }],
    },
    options,
  }));

  makeTable("yearTable", [
    { key: "year", label: "Year" },
    { key: "cases", label: "FIRs", show: v => fmt(v) },
    { key: "per_100k", label: "Per lakh", show: v => fmt(v, 2) },
  ], D.cases_by_year);

  makeTable("growthTable", [
    { key: "state", label: "State/UT" },
    { key: "cases_2023", label: "2023", show: v => fmt(v) },
    { key: "cases_2024", label: "2024", show: v => fmt(v) },
    { key: "yoy_growth_pct", label: "Growth", show: v => (v > 0 ? "+" : "") + fmt(v, 1) + "%" },
    { key: "trend_flag", label: "Flag" },
  ], D.growth_2024.slice(0, 10), r => r.trend_flag === "Surge");
}

// ---------- 6. fraud types ------------------------------------------------

function drawTypes() {
  const y2023 = D.fraud_types.filter(r => r.year === 2023);
  const options = baseOptions();
  options.indexAxis = "y";
  options.scales.y.grid.display = false;
  options.scales.y.ticks.color = css("--text-2");
  options.scales.x.title = { display: true, text: "Share of cyber fraud cases (%)", color: css("--text-2") };
  options.plugins.tooltip.callbacks = {
    label: item => `${fmt(y2023[item.dataIndex].cases)} cases, ${fmt(y2023[item.dataIndex].pct_of_fraud_cases, 1)}%`,
  };
  charts.push(new Chart(document.getElementById("typeChart"), {
    type: "bar",
    data: {
      labels: y2023.map(r => r.fraud_type),
      datasets: [{ data: y2023.map(r => r.pct_of_fraud_cases), backgroundColor: css("--series-1"),
                   borderRadius: 4, borderSkipped: "start", categoryPercentage: 0.8 }],
    },
    options,
  }));

  // one row per type, one column per year
  const years = [...new Set(D.fraud_types.map(r => r.year))];
  const types = [...new Set(D.fraud_types.map(r => r.fraud_type))];
  const wide = types.map(t => {
    const row = { fraud_type: t };
    years.forEach(y => { row[y] = D.fraud_types.find(r => r.year === y && r.fraud_type === t).cases; });
    return row;
  });
  makeTable("typeTable", [{ key: "fraud_type", label: "Type" }]
    .concat(years.map(y => ({ key: y, label: String(y), show: v => fmt(v) }))), wide);
}

// ---------- draw everything ---------------------------------------------

function drawAll() {
  charts.splice(0).forEach(c => c.destroy());
  Chart.defaults.font.family = 'system-ui, -apple-system, "Segoe UI", sans-serif';
  Chart.defaults.locale = "en-IN";           // axis ticks as 1,20,000 like the rest of the page
  Chart.defaults.color = css("--text-2");
  rateChart = null;                           // destroyed just above with the others
  drawTiles();
  drawQuadrant();
  drawConversion();
  drawRateYears();
  drawRate();
  drawFunnel();
  drawMoney();
  drawGrowth();
  drawTypes();
}

drawAll();
// redraw with the other palette when the colour theme changes: the device's
// light/dark setting, or the theme button in the menu bar
window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", () => {
  drawAll();
  window.dispatchEvent(new Event("themechange"));
});
window.addEventListener("themetoggle", () => {
  drawAll();
  window.dispatchEvent(new Event("themechange"));
});
